import type { ChangeLevel, OperationChange } from "./diff.js";
import type { DocPage } from "./emit-docs.js";
import type { HistoryEntry } from "./history.js";
import { groupByMinor } from "./history.js";

/**
 * The marker placed below the title of every generated page.
 */
const GENERATED =
  "<!-- Generated by @virtbase/proxmox-api-generator. Do not edit. -->";

/**
 * How each change level is worded for readers of the changelog.
 */
const LEVEL_LABEL: Record<ChangeLevel, string> = {
  major: "Breaking",
  minor: "Additive",
  patch: "Documentation only",
  none: "No changes",
};

/**
 * Renders the frontmatter of a generated page, with the edit link disabled
 * and a blank line after the block.
 *
 * @param title - The page title, written into the YAML unquoted.
 */
function frontmatter(title: string): string[] {
  return ["---", `title: ${title}`, "editLink: false", "---", ""];
}

/**
 * Renders one `###` section listing operations and, nested below each, the
 * details of what changed.
 *
 * @remarks
 * An operation is flagged as breaking only under the kind `changed`; a
 * removed or added operation carries no flag of its own. Breaking details
 * are flagged individually.
 *
 * @param heading - The section title, e.g. `Removed`.
 * @param changes - The operations to list, kept in the given order.
 * @returns The Markdown lines, starting with a blank line, or an empty array
 *   when there is nothing to list.
 */
function operationList(heading: string, changes: OperationChange[]): string[] {
  if (changes.length === 0) return [];
  const lines = ["", `### ${heading}`, ""];
  for (const change of changes) {
    const flag =
      change.breaking && change.change === "changed" ? " — **breaking**" : "";
    lines.push(`- \`${change.operation}\`${flag}`);
    for (const detail of change.details ?? []) {
      lines.push(
        `  - ${detail.text}${detail.breaking ? " **(breaking)**" : ""}`,
      );
    }
  }
  return lines;
}

/**
 * Renders the `##` section of one schema version.
 *
 * @remarks
 * The section holds a line of facts (publication date when known, the
 * version compared with, the operation count and the impact), then the
 * types no longer exported, then the removed, changed and added operations
 * in that order, and last the number of operations that changed in wording
 * only. Parts with nothing to report are left out. The first tracked version
 * has no predecessor and therefore states no impact.
 *
 * @param entry - The version and its differences from the one before.
 * @returns The Markdown lines, starting with a blank line.
 */
function renderEntry(entry: HistoryEntry): string[] {
  const facts = [
    entry.released ? `Published ${entry.released}` : undefined,
    entry.previous
      ? `compared with ${entry.previous}`
      : "first tracked version",
    `${entry.operations} operations`,
    entry.previous ? LEVEL_LABEL[entry.level].toLowerCase() : undefined,
  ].filter(Boolean);

  const lines = ["", `## ${entry.version}`, "", `${facts.join(" · ")}.`];
  /**
   * Selects the entry's changes of one kind, in their stored order.
   */
  const by = (kind: OperationChange["change"]) =>
    entry.changes.filter((change) => change.change === kind);
  if (entry.removedTypes?.length) {
    lines.push(
      "",
      "### Renamed or removed types",
      "",
      "No longer exported from the `Proxmox` namespace — **breaking** for code",
      "that imports them by name:",
      "",
      ...entry.removedTypes.map((name) => `- \`${name}\``),
    );
  }
  lines.push(
    ...operationList("Removed", by("removed")),
    ...operationList("Changed", by("changed")),
    ...operationList("Added", by("added")),
  );
  if (entry.summary.documentation > 0) {
    lines.push(
      "",
      `Descriptions or metadata changed on ${entry.summary.documentation} other operation${entry.summary.documentation === 1 ? "" : "s"}.`,
    );
  }
  return lines;
}

/**
 * Builds the API changelog: one page per Proxmox VE minor release, plus an
 * index.
 *
 * @remarks
 * The index holds one table row per version. Each row links to the version's
 * heading on its release page and gives the counts of added, removed and
 * changed operations and the impact, which reads `Baseline` for the first
 * tracked version.
 *
 * @param entries - Every tracked schema version, in any order.
 * @returns The index page (slug `index`) first, then one page per release
 *   (slug `pve-<major>.<minor>`), newest release first. Within a page and in
 *   the index table the newest version comes first.
 */
export function emitChangelog(entries: HistoryEntry[]): DocPage[] {
  const groups = groupByMinor(entries);

  const pages: DocPage[] = groups.map(({ minor, entries: group }) => ({
    slug: `pve-${minor}`,
    title: `Proxmox VE ${minor}`,
    markdown: [
      ...frontmatter(`API changes in Proxmox VE ${minor}`),
      `# API changes in Proxmox VE ${minor}`,
      "",
      GENERATED,
      "",
      "Differences between consecutive versions of the published API schema.",
      "Anything marked **breaking** removes or narrows something callers could",
      "rely on; everything else is additive.",
      ...group.flatMap(renderEntry),
      "",
    ].join("\n"),
  }));

  pages.unshift({
    slug: "index",
    title: "Overview",
    markdown: [
      ...frontmatter("API changelog"),
      "# API changelog",
      "",
      GENERATED,
      "",
      "Every version of the Proxmox VE API schema this package has tracked, and",
      "what changed in each. The schema comes from the `pve-docs` package, so",
      "versions are `pve-docs` versions; the first two numbers are the Proxmox VE",
      "release.",
      "",
      "| Schema | Published | Operations | Added | Removed | Changed | Impact |",
      "| --- | --- | ---: | ---: | ---: | ---: | --- |",
      ...groups.flatMap(({ minor, entries: group }) =>
        group.map((entry) => {
          // VitePress puts `_` in front of a heading anchor that starts with
          // a digit, hence the `#_` in the link below.
          const anchor = entry.version.replace(/\./g, "-");
          const { added, removed, changed } = entry.summary;
          return `| [${entry.version}](./pve-${minor}#_${anchor}) | ${entry.released ?? ""} | ${entry.operations} | ${added} | ${removed} | ${changed} | ${entry.previous ? LEVEL_LABEL[entry.level] : "Baseline"} |`;
        }),
      ),
      "",
    ].join("\n"),
  });

  return pages;
}

/**
 * Builds the sidebar entries for the changelog pages, for the VitePress
 * config.
 *
 * @param pages - The pages returned by {@link emitChangelog}.
 * @returns One entry per page, in the given order. The index page links to
 *   `/reference/api-changelog/`, every other page to its slug below that.
 */
export function changelogSidebar(
  pages: DocPage[],
): Array<{ text: string; link: string }> {
  return pages.map((page) => ({
    text: page.title,
    link: `/reference/api-changelog/${page.slug === "index" ? "" : page.slug}`,
  }));
}

/**
 * Renders a short plain-text summary of one schema update, for commit
 * messages and pull request bodies.
 *
 * @remarks
 * Three lines always appear: the versions compared (`?` stands in for a
 * missing predecessor), the impact, and the operation counts. The types no
 * longer exported and the breaking operations follow when there are any,
 * each list cut off after 40 items with a note of how many were left out. A
 * breaking operation is followed by its breaking details, with backticks
 * removed, or by the kind of change when it has none.
 *
 * @param entry - The version and its differences from the one before.
 * @returns The summary, lines joined by `\n`, without a trailing newline.
 */
export function summarize(entry: HistoryEntry): string {
  const { added, removed, changed, breaking, documentation } = entry.summary;
  const lines = [
    `Schema: pve-docs ${entry.previous ?? "?"} -> ${entry.version} (${entry.operations} operations)`,
    `Impact: ${LEVEL_LABEL[entry.level]}`,
    `Operations added: ${added}, removed: ${removed}, changed: ${changed} (${breaking} breaking), documentation only: ${documentation}`,
  ];
  if (entry.removedTypes?.length) {
    const shown = entry.removedTypes.slice(0, 40).join(", ");
    const more = entry.removedTypes.length - 40;
    lines.push(
      "",
      `Renamed or removed types (breaking): ${shown}${more > 0 ? `, and ${more} more` : ""}`,
    );
  }
  const breakingChanges = entry.changes.filter((change) => change.breaking);
  if (breakingChanges.length > 0) {
    lines.push("", "Breaking:");
    for (const change of breakingChanges.slice(0, 40)) {
      const details = (change.details ?? [])
        .filter((detail) => detail.breaking)
        .map((detail) => detail.text.replace(/`/g, ""))
        .join("; ");
      lines.push(
        `- ${change.operation}${details ? `: ${details}` : ` ${change.change}`}`,
      );
    }
    if (breakingChanges.length > 40) {
      lines.push(`- ...and ${breakingChanges.length - 40} more`);
    }
  }
  return lines.join("\n");
}
